import 'package:flutter/material.dart';

void main() => runApp(const SightGuideApp());

class SightGuideApp extends StatelessWidget {
  const SightGuideApp({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(
    title: 'SightGuide AI', debugShowCheckedModeBanner: false,
    theme: ThemeData(useMaterial3: true, colorScheme: ColorScheme.fromSeed(seedColor: const Color(0xFF087F72), brightness: Brightness.light), scaffoldBackgroundColor: const Color(0xFFF5F8F7), fontFamily: 'Roboto'),
    home: const HomeShell(),
  );
}

class HomeShell extends StatefulWidget { const HomeShell({super.key}); @override State<HomeShell> createState() => _HomeShellState(); }
class _HomeShellState extends State<HomeShell> {
  int tab = 0; bool connected = false; bool demoAlerts = false;
  @override Widget build(BuildContext context) {
    final pages = [Dashboard(connected: connected, onConnect: () => setState(() => connected = !connected), onDemo: () => setState(() => demoAlerts = !demoAlerts), demoAlerts: demoAlerts), const FeaturesPage(), const PeoplePage(), const SettingsPage()];
    return Scaffold(body: SafeArea(child: pages[tab]), bottomNavigationBar: NavigationBar(selectedIndex: tab, onDestinationSelected: (v) => setState(() => tab = v), destinations: const [NavigationDestination(icon: Icon(Icons.home_outlined), selectedIcon: Icon(Icons.home), label: 'Home'), NavigationDestination(icon: Icon(Icons.explore_outlined), label: 'Explore'), NavigationDestination(icon: Icon(Icons.people_outline), label: 'People'), NavigationDestination(icon: Icon(Icons.settings_outlined), label: 'Settings')]));
  }
}

