class _Tile extends StatelessWidget {final IconData icon;final String title,subtitle;final Color color;final VoidCallback onTap;const _Tile({required this.icon,required this.title,required this.subtitle,required this.color,required this.onTap});@override Widget build(BuildContext context)=>InkWell(onTap:onTap,borderRadius:BorderRadius.circular(18),child:Container(padding:const EdgeInsets.all(15),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(18)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,mainAxisAlignment:MainAxisAlignment.center,children:[Container(padding:const EdgeInsets.all(9),decoration:BoxDecoration(color:color,borderRadius:BorderRadius.circular(12)),child:Icon(icon,color:const Color(0xFF174E49))),const SizedBox(height:9),Text(title,style:const TextStyle(fontWeight:FontWeight.bold)),Text(subtitle,style:const TextStyle(color:Colors.black54,fontSize:12))])));}
Widget _status(String title,String value,IconData icon)=>Container(padding:const EdgeInsets.all(15),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(16)),child:Row(children:[Icon(icon,color:const Color(0xFF087F72)),const SizedBox(width:9),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(color:Colors.black54,fontSize:12)),Text(value,style:const TextStyle(fontWeight:FontWeight.bold))]))]));
